  // ========== 工具函数 ==========

  function $(id) { return document.getElementById(id); }
  function val(id) { return ($(id) || {}).value || ''; }
  function setVal(id, v) { var el = $(id); if (el) el.value = v || ''; }

  function showToast(msg) {
    var toast = $('toast');
    toast.textContent = msg;
    toast.classList.add('show');
    setTimeout(function() { toast.classList.remove('show'); }, 2200);
  }

  function copyToClipboard(text) {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text).then(function() {
        showToast('已复制到剪贴板');
      }).catch(function() {
        fallbackCopy(text);
      });
    } else {
      fallbackCopy(text);
    }
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); showToast('已复制到剪贴板'); }
    catch(e) { showToast('复制失败，请手动选择复制'); }
    document.body.removeChild(ta);
  }

  // ========== 关键词管理 ==========

  function renderKeywordTags() {
    var container = $('keyword-tags');
    container.innerHTML = '';
    state.keywords.forEach(function(kw, idx) {
      var tag = document.createElement('span');
      tag.className = 'keyword-tag';
      tag.innerHTML = kw + ' <span class="remove-tag" data-idx="' + idx + '">×</span>';
      tag.querySelector('.remove-tag').onclick = function() {
        state.keywords.splice(idx, 1);
        renderKeywordTags();
        saveToStorage();
      };
      container.appendChild(tag);
    });
  }

  function addKeyword(kw) {
    kw = (kw || '').trim();
    if (!kw) return;
    if (state.keywords.indexOf(kw) !== -1) return;
    state.keywords.push(kw);
    renderKeywordTags();
    saveToStorage();
  }

  // 从JD文本中提取关键词
  function extractKeywords() {
    var duties = val('job-duties');
    var requirements = val('job-requirements');
    var text = duties + '\n' + requirements;

    if (!text.trim()) {
      showToast('请先填写岗位职责或任职要求');
      return;
    }

    var found = new Set();

    // 1. 词典匹配
    SKILL_DICT.forEach(function(skill) {
      if (text.indexOf(skill) !== -1) {
        found.add(skill);
      }
    });

    // 2. 从任职要求中按行提取（常见格式：熟悉xxx、精通xxx）
    var lines = text.split(/[\n\r;；]+/);
    lines.forEach(function(line) {
      // 匹配 "熟悉/精通/掌握/了解 + 内容" 模式
      var patterns = [
        /(?:熟悉|精通|掌握|了解|熟练使用|熟练掌握|能使用|会使用|能熟练)\s*([A-Za-z0-9\u4e00-\u9fa5\/、,，\+\.\#\-]{2,30})/g,
        /(?:使用|运用|应用)\s*([A-Za-z0-9\u4e00-\u9fa5\/、,，\+\.\#\-]{2,30})/g
      ];
      patterns.forEach(function(p) {
        var m;
        while ((m = p.exec(line)) !== null) {
          var term = m[1].trim();
          // 清理尾部标点
          term = term.replace(/[、,，。.；;等]+$/,'').trim();
          if (term.length >= 2 && term.length <= 20 && !STOP.has(term)) {
            found.add(term);
          }
        }
      });
    });

    // 3. 提取英文词汇（2-20字母）
    var enMatches = text.match(/[A-Za-z][A-Za-z0-9\.\-\+#]{1,19}/g);
    if (enMatches) {
      enMatches.forEach(function(w) {
        var lower = w.toLowerCase();
        // 过滤太短或太长的
        if (w.length >= 2 && w.length <= 20) {
          // 过滤常见非技能词
          var nonSkill = ['the','and','for','with','from','this','that','have','will','your','our','you','are','was','were','been','being','have','has','had','can','could','should','would','may','might','must','shall','will','need','dare','used','into','onto','upon','over','under','above','below','before','after','during','while','since','until','between','among','through','throughout','around','about','against','without','within','along','across','behind','beyond','beside','near','off','toward','towards','upon','via','per','than','then','them','they','their','there','these','those','what','which','who','whom','whose','when','where','why','how','all','any','both','each','few','more','most','other','some','such','only','own','same','very','just','now'];
          if (nonSkill.indexOf(lower) === -1 && !STOP.has(w)) {
            found.add(w);
          }
        }
      });
    }

    // 合并到现有关键词
    var newCount = 0;
    found.forEach(function(kw) {
      if (state.keywords.indexOf(kw) === -1) {
        state.keywords.push(kw);
        newCount++;
      }
    });

    renderKeywordTags();
    saveToStorage();
    showToast('提取完成，新增 ' + newCount + ' 个关键词（共 ' + state.keywords.length + ' 个）');
  }

  // ========== 岗位智能拆解 (Module 2) ==========

  function autoAnalyzeJob() {
    var duties = val('job-duties');
    var requirements = val('job-requirements');
    var preferences = val('job-preferences');
    var title = val('job-title');
    var text = duties + '\n' + requirements;

    if (!text.trim()) {
      showToast('请先在模块1中填写岗位职责和任职要求');
      return;
    }

    // 核心能力提炼
    var coreAbilities = [];
    var abilityPatterns = [
      { pattern: /产品(?:规划|设计|迭代|策略|路线图)/g, ability: '产品规划与设计能力' },
      { pattern: /(?:数据分析|数据驱动|数据决策|数据挖掘)/g, ability: '数据分析与驱动决策能力' },
      { pattern: /(?:跨部门|协作|沟通|协调)/g, ability: '跨部门协作与沟通能力' },
      { pattern: /(?:项目管理|项目推进|项目落地)/g, ability: '项目管理与推进能力' },
      { pattern: /(?:用户(?:研究|调研|增长|运营))/g, ability: '用户洞察与运营能力' },
      { pattern: /(?:团队管理|带团队|团队建设)/g, ability: '团队管理能力' },
      { pattern: /(?:商业化|变现|盈利|营收)/g, ability: '商业化与变现能力' },
      { pattern: /(?:技术(?:架构|方案|选型|设计))/g, ability: '技术架构与设计能力' },
      { pattern: /(?:前端|后端|全栈|开发)/g, ability: '系统开发与工程能力' },
      { pattern: /(?:测试|质量|自动化测试)/g, ability: '质量保障与测试能力' },
      { pattern: /(?:运维|部署|监控|容器)/g, ability: '运维与部署能力' },
      { pattern: /(?:机器学习|深度学习|大模型|AI|算法)/g, ability: 'AI算法与模型能力' },
      { pattern: /(?:内容运营|用户运营|活动运营|社群运营)/g, ability: '运营策划与执行能力' },
      { pattern: /(?:营销|品牌|推广|投放)/g, ability: '营销推广与品牌建设能力' },
      { pattern: /(?:财务|预算|成本|审计)/g, ability: '财务管理与分析能力' },
      { pattern: /(?:供应链|采购|物流|仓储)/g, ability: '供应链管理能力' },
      { pattern: /(?:销售|客户|商务|BD)/g, ability: '商务拓展与客户管理能力' },
      { pattern: /(?:战略|规划|商业洞察)/g, ability: '战略规划与商业洞察能力' }
    ];

    abilityPatterns.forEach(function(item) {
      if (item.pattern.test(text) && coreAbilities.indexOf(item.ability) === -1) {
        coreAbilities.push(item.ability);
      }
    });

    // 如果提取不足3条，根据岗位名称补充
    if (coreAbilities.length < 3) {
      if (title.indexOf('产品') !== -1) {
        ['产品规划与设计能力','数据分析与驱动决策能力','跨部门协作与沟通能力'].forEach(function(a) {
          if (coreAbilities.indexOf(a) === -1) coreAbilities.push(a);
        });
      } else if (title.indexOf('开发') !== -1 || title.indexOf('工程师') !== -1) {
        ['系统开发与工程能力','技术架构与设计能力','质量保障与测试能力'].forEach(function(a) {
          if (coreAbilities.indexOf(a) === -1) coreAbilities.push(a);
        });
      } else if (title.indexOf('运营') !== -1) {
        ['运营策划与执行能力','数据分析与驱动决策能力','用户洞察与运营能力'].forEach(function(a) {
          if (coreAbilities.indexOf(a) === -1) coreAbilities.push(a);
        });
      } else if (title.indexOf('设计') !== -1) {
        ['产品规划与设计能力','用户体验设计能力','跨部门协作与沟通能力'].forEach(function(a) {
          if (coreAbilities.indexOf(a) === -1) coreAbilities.push(a);
        });
      }
    }

    // 限制3-5条
    coreAbilities = coreAbilities.slice(0, 5);
    var coreText = coreAbilities.map(function(a, i) { return (i+1) + '. ' + a; }).join('\n');
    setVal('analysis-core', coreText);

    // 硬技能提取
    var hardSkills = [];
    SKILL_DICT.forEach(function(skill) {
      if (text.indexOf(skill) !== -1 && hardSkills.indexOf(skill) === -1) {
        // 判断是否为硬技能（排除纯软技能）
        var softSkills = ['团队管理','跨部门协作','沟通能力','抗压能力','执行力','逻辑思维','解决问题','演讲能力','英语','日语','法语'];
        if (softSkills.indexOf(skill) === -1) {
          hardSkills.push(skill);
        }
      }
    });
    setVal('analysis-hard-skills', hardSkills.join('\n'));

    // 软技能/加分技能
    var softSkills = [];
    var softPatterns = [
      { pattern: /团队管理|管理经验/, skill: '团队管理经验' },
      { pattern: /(?:电商|金融|教育|医疗|游戏|SaaS)/, skill: '' }, // 行业经验动态提取
      { pattern: /0.?1|从零|从0/, skill: '0-1产品/项目经验' },
      { pattern: /大厂|知名互联网|头部/, skill: '大厂经验' },
      { pattern: /英语|English/, skill: '英语能力' },
      { pattern: /(?:抗压|压力)/, skill: '抗压能力' },
      { pattern: /(?:沟通|协作)/, skill: '沟通协作能力' },
      { pattern: /(?:学习|自驱|主动)/, skill: '学习能力与自驱力' },
      { pattern: /(?:领导|带队)/, skill: '领导力' },
      { pattern: /(?:创业|初创)/, skill: '创业公司经验' }
    ];
    softPatterns.forEach(function(item) {
      if (item.pattern.test(text) && item.skill && softSkills.indexOf(item.skill) === -1) {
        softSkills.push(item.skill);
      }
    });

    // 行业经验
    var industries = ['电商','金融','教育','医疗','游戏','SaaS','B2B','B2C','社交','内容','短视频','直播','跨境','供应链','物流','制造','汽车','新能源'];
    industries.forEach(function(ind) {
      if (text.indexOf(ind) !== -1) {
        softSkills.push(ind + '行业经验');
      }
    });
    setVal('analysis-soft-skills', softSkills.join('\n'));

    // 高频关键词
    setVal('analysis-keywords', state.keywords.join('、'));

    // 隐藏要求
    var hidden = [];
    var hiddenPatterns = [
      { pattern: /大厂|知名互联网|头部/, text: '有大厂经验优先' },
      { pattern: /0.?1|从零|从0/, text: '有从0到1项目经验' },
      { pattern: /加班|996|高强度/, text: '能接受加班/高强度工作' },
      { pattern: /出差/, text: '能接受出差' },
      { pattern: /创业|初创/, text: '适应创业公司节奏' },
      { pattern: /管理|带团队/, text: '有团队管理经验' },
      { pattern: /英语|English/, text: '英语可作为工作语言' },
      { pattern: /硕士|博士|985|211/, text: '985/211或硕士以上学历优先' }
    ];
    hiddenPatterns.forEach(function(item) {
      if (item.pattern.test(text) && hidden.indexOf(item.text) === -1) {
        hidden.push(item.text);
      }
    });
    if (hidden.length === 0) hidden.push('无明显隐藏要求，但建议关注企业文化匹配度');
    setVal('analysis-hidden', hidden.join('\n'));

    saveToStorage();
    showToast('岗位拆解完成，已自动填充各分析项');
  }

