  function escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  // ========== 匹配分析引擎 (Module 4) ==========

  function runMatchAnalysis() {
    // 收集所有简历文本
    var resumeText = collectResumeText();

    // 收集JD关键词
    var jdKeywords = state.keywords.slice();
    var hardSkills = val('analysis-hard-skills').split(/[\n,，、;；]+/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var softSkills = val('analysis-soft-skills').split(/[\n,，、;；]+/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var allJdKeywords = jdKeywords.concat(hardSkills);

    if (allJdKeywords.length === 0) {
      showToast('请先在模块1提取关键词或在模块2填写技能要求');
      return;
    }
    if (!resumeText.trim()) {
      showToast('请先在模块3填写简历信息');
      return;
    }

    // 去重
    var uniqueKeywords = [];
    allJdKeywords.forEach(function(kw) {
      if (uniqueKeywords.indexOf(kw) === -1) uniqueKeywords.push(kw);
    });

    // 关键词匹配
    var matchedKeywords = [];
    var missingKeywords = [];
    uniqueKeywords.forEach(function(kw) {
      // 模糊匹配：不区分大小写
      var lower = kw.toLowerCase();
      var lowerResume = resumeText.toLowerCase();
      if (lowerResume.indexOf(lower) !== -1) {
        matchedKeywords.push(kw);
      } else {
        missingKeywords.push(kw);
      }
    });

    // 硬技能匹配分析
    var hardMatched = [];
    var hardMissing = [];
    hardSkills.forEach(function(skill) {
      if (resumeText.toLowerCase().indexOf(skill.toLowerCase()) !== -1) {
        hardMatched.push(skill);
      } else {
        hardMissing.push(skill);
      }
    });

    // 冗余项：简历中有但JD中没有的技能
    var resumeSkills = val('resume-skills').split(/[\n,，、;；]+/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var redundantSkills = [];
    resumeSkills.forEach(function(skill) {
      var found = false;
      uniqueKeywords.forEach(function(kw) {
        if (skill.toLowerCase().indexOf(kw.toLowerCase()) !== -1 || kw.toLowerCase().indexOf(skill.toLowerCase()) !== -1) {
          found = true;
        }
      });
      if (!found) redundantSkills.push(skill);
    });

    // 经验匹配
    var yearsText = val('resume-years');
    var yearsMatch = yearsText.match(/(\d+)/);
    var years = yearsMatch ? parseInt(yearsMatch[1]) : 0;
    var reqYearsMatch = val('job-requirements').match(/(\d+)\s*年/);
    var reqYears = reqYearsMatch ? parseInt(reqYearsMatch[1]) : 0;
    var expScore = 0;
    if (reqYears > 0 && years > 0) {
      expScore = Math.min(years / reqYears, 1) * 100;
    } else if (years > 0) {
      expScore = 70; // 有经验但无法对比年限
    } else {
      expScore = 30; // 无法判断
    }

    // 优势匹配
    var highlights = val('resume-highlights');
    var preferences = val('job-preferences');
    var advScore = 0;
    if (highlights && preferences) {
      var prefWords = preferences.split(/[、,，\s]+/).filter(function(s){return s.length > 1;});
      var matchedPrefs = 0;
      prefWords.forEach(function(pref) {
        if (highlights.indexOf(pref) !== -1) matchedPrefs++;
      });
      advScore = prefWords.length > 0 ? (matchedPrefs / prefWords.length) * 100 : 50;
    } else {
      advScore = 40;
    }

    // 计算各项分数
    var hardScore = hardSkills.length > 0 ? (hardMatched.length / hardSkills.length) * 100 : 50;
    var kwScore = uniqueKeywords.length > 0 ? (matchedKeywords.length / uniqueKeywords.length) * 100 : 0;

    // 加权总分
    var totalScore = Math.round(
      hardScore * 0.35 +
      kwScore * 0.30 +
      expScore * 0.20 +
      advScore * 0.15
    );

    // 保存结果
    state.matchResult = {
      totalScore: totalScore,
      hardScore: Math.round(hardScore),
      expScore: Math.round(expScore),
      kwScore: Math.round(kwScore),
      advScore: Math.round(advScore),
      matchedKeywords: matchedKeywords,
      missingKeywords: missingKeywords,
      hardMatched: hardMatched,
      hardMissing: hardMissing,
      redundantSkills: redundantSkills,
      totalKeywords: uniqueKeywords.length
    };

    renderMatchResults();
    saveToStorage();
    showToast('匹配分析完成！总分：' + totalScore + '分');
  }

  function collectResumeText() {
    var parts = [];
    // 基本信息
    parts.push(val('resume-name'));
    parts.push(val('resume-current-title'));
    parts.push(val('resume-years'));
    parts.push(val('resume-education'));
    parts.push(val('resume-certificates'));
    // 技能
    parts.push(val('resume-skills'));
    // 优势亮点
    parts.push(val('resume-highlights'));
    // 工作经历
    state.workExperiences.forEach(function(exp) {
      if (exp) {
        parts.push(exp.company);
        parts.push(exp.position);
        parts.push(exp.content);
        parts.push(exp.achievement);
      }
    });
    // 项目经历
    state.projectExperiences.forEach(function(proj) {
      if (proj) {
        parts.push(proj.name);
        parts.push(proj.role);
        parts.push(proj.action);
        parts.push(proj.result);
      }
    });
    return parts.join(' ');
  }

  function renderMatchResults() {
    var r = state.matchResult;
    if (!r) return;

    $('match-empty').style.display = 'none';
    $('match-content').style.display = 'block';

    // 分数圆环
    var circumference = 326.7;
    var offset = circumference - (r.totalScore / 100) * circumference;
    $('score-circle-fill').style.strokeDashoffset = offset;
    $('score-num').textContent = r.totalScore;

    // 分数颜色
    var scoreColor = r.totalScore >= 80 ? 'var(--success)' : r.totalScore >= 60 ? 'var(--accent)' : r.totalScore >= 40 ? 'var(--warning)' : 'var(--danger)';
    $('score-num').style.color = scoreColor;

    // 各项进度条
    setBar('bar-hard', r.hardScore, 'bar-hard-value', r.hardScore + '%');
    setBar('bar-exp', r.expScore, 'bar-exp-value', r.expScore + '%');
    setBar('bar-kw', r.kwScore, 'bar-kw-value', r.matchedKeywords.length + '/' + r.totalKeywords);
    setBar('bar-adv', r.advScore, 'bar-adv-value', r.advScore + '%');

    // 硬技能匹配列表
    var hardList = $('hard-skills-list');
    hardList.innerHTML = '';
    r.hardMatched.forEach(function(s) {
      hardList.innerHTML += '<li><span class="status-icon ok">✓</span>' + escapeHtml(s) + '</li>';
    });
    r.hardMissing.forEach(function(s) {
      hardList.innerHTML += '<li><span class="status-icon no">✗</span>' + escapeHtml(s) + '</li>';
    });
    if (r.hardMatched.length === 0 && r.hardMissing.length === 0) {
      hardList.innerHTML = '<li style="color:var(--muted)">未配置硬技能对比项</li>';
    }
    $('hard-matched-count').textContent = r.hardMatched.length;

    // 缺失项
    var missingList = $('missing-list');
    missingList.innerHTML = '';
    r.missingKeywords.forEach(function(s) {
      missingList.innerHTML += '<li><span class="status-icon no">✗</span>' + escapeHtml(s) + '</li>';
    });
    if (r.missingKeywords.length === 0) {
      missingList.innerHTML = '<li style="color:var(--success)"><span class="status-icon ok">✓</span>关键词全部命中！</li>';
    }
    $('missing-count').textContent = r.missingKeywords.length;

    // 关键词命中标签
    var kwTags = $('keyword-match-tags');
    kwTags.innerHTML = '';
    r.matchedKeywords.forEach(function(kw) {
      kwTags.innerHTML += '<span class="keyword-tag matched">' + escapeHtml(kw) + '</span>';
    });
    r.missingKeywords.forEach(function(kw) {
      kwTags.innerHTML += '<span class="keyword-tag missing">' + escapeHtml(kw) + '</span>';
    });
    if (r.totalKeywords === 0) {
      kwTags.innerHTML = '<span style="color:var(--muted);font-size:0.8rem">无关键词</span>';
    }

    // 冗余项
    var redundantList = $('redundant-list');
    redundantList.innerHTML = '';
    r.redundantSkills.forEach(function(s) {
      redundantList.innerHTML += '<li><span class="status-icon partial">○</span>' + escapeHtml(s) + '</li>';
    });
    if (r.redundantSkills.length === 0) {
      redundantList.innerHTML = '<li style="color:var(--muted)">无冗余技能</li>';
    }
    $('redundant-count').textContent = r.redundantSkills.length;

    // 改善建议
    var suggestions = generateSuggestions(r);
    $('match-suggestions').textContent = suggestions;
  }

  function setBar(barId, score, valueId, valueText) {
    var bar = $(barId);
    bar.style.width = score + '%';
    bar.className = 'bar-fill';
    if (score >= 80) bar.classList.add('success');
    else if (score < 50) bar.classList.add('danger');
    else if (score < 70) bar.classList.add('warning');
    $(valueId).textContent = valueText;
  }

  function generateSuggestions(r) {
    var suggestions = [];

    if (r.totalScore >= 85) {
      suggestions.push('✓ 整体匹配度很高，可以直接投递！');
    } else if (r.totalScore >= 70) {
      suggestions.push('△ 匹配度较好，稍作优化即可投递。');
    } else if (r.totalScore >= 50) {
      suggestions.push('△ 匹配度一般，需要针对性优化简历后再投递。');
    } else {
      suggestions.push('✗ 匹配度较低，建议仔细评估是否适合该岗位。');
    }

    if (r.hardMissing.length > 0) {
      suggestions.push('\n【硬技能缺口】以下技能岗位要求但简历未体现：');
      suggestions.push(r.hardMissing.slice(0, 5).join('、'));
      suggestions.push('→ 建议在简历中补充相关技能的学习/实践经历，或在技能清单中明确列出。');
    }

    if (r.missingKeywords.length > 0) {
      suggestions.push('\n【关键词缺失】以下关键词在简历中未命中：');
      suggestions.push(r.missingKeywords.slice(0, 8).join('、'));
      suggestions.push('→ 建议在工作内容、项目经历中自然融入这些关键词，提高HR筛选通过率。');
    }

    if (r.redundantSkills.length > 3) {
      suggestions.push('\n【简历精简】简历中有 ' + r.redundantSkills.length + ' 项技能与岗位无关。');
      suggestions.push('→ 建议精简或弱化这些内容，突出与岗位相关的技能和经验。');
    }

    if (r.expScore < 60) {
      suggestions.push('\n【经验不足】工作年限可能不满足岗位要求。');
      suggestions.push('→ 建议在简历中突出项目成果和数据，用能力弥补年限差距。');
    }

    if (r.advScore < 50) {
      suggestions.push('\n【优势匹配度低】你的个人亮点与岗位偏好匹配度不高。');
      suggestions.push('→ 建议重新梳理个人优势亮点，使其更贴合岗位核心需求。');
    }

    return suggestions.join('\n');
  }

  // ========== 简历优化输出 (Module 5) ==========

  function generateOptimizedResume() {
    var name = val('resume-name') || '【姓名】';
    var title = val('resume-current-title') || '【职位】';
    var years = val('resume-years') || '【年限】';
    var education = val('resume-education') || '【学历】';
    var jobTitle = val('job-title') || '目标岗位';
    var company = val('job-company') || '目标公司';

    // 检查是否有足够数据
    if (!val('resume-skills') && state.workExperiences.length === 0) {
      showToast('请先在模块3填写简历信息');
      return;
    }

    var r = state.matchResult;
    var matchedKw = r ? r.matchedKeywords : state.keywords.slice(0, 5);
    var highlights = val('resume-highlights');

    // 1. 个人简介（约100字）
    var introParts = [];
    introParts.push(years + '经验' + title);
    if (highlights) {
      // 提取第一条亮点
      var firstHighlight = highlights.split(/[\n\r]+/)[0].replace(/^\d+[.、\)]\s*/, '');
      introParts.push(firstHighlight);
    }
    // 加入匹配的关键词
    if (matchedKw.length > 0) {
      introParts.push('擅长' + matchedKw.slice(0, 4).join('、'));
    }
    introParts.push('寻求' + jobTitle + '机会，期望在' + (val('job-industry') || '相关') + '领域持续深耕');
    var intro = introParts.join('，') + '。';
    // 控制在100字左右
    if (intro.length > 120) {
      intro = intro.substring(0, 117) + '...';
    }
    setOutput('output-intro', intro);

    // 2. 工作经历改写
    var workText = '';
    state.workExperiences.forEach(function(exp, i) {
      if (!exp || !exp.company) return;
      workText += '■ ' + exp.company + ' | ' + exp.position + ' | ' + exp.period + '\n';
      if (exp.content) {
        workText += '  工作内容：\n';
        exp.content.split(/[\n\r]+/).forEach(function(line) {
          workText += '    • ' + line.replace(/^\d+[.、\)]\s*/, '') + '\n';
        });
      }
      if (exp.achievement) {
        workText += '  工作成果：\n';
        exp.achievement.split(/[\n\r]+/).forEach(function(line) {
          // 如果成果中没有数据，提示添加
          workText += '    ★ ' + line.replace(/^\d+[.、\)]\s*/, '') + '\n';
        });
      }
      workText += '\n';
    });
    if (!workText) workText = '【请在模块3中添加工作经历】';
    setOutput('output-work', workText.trim());

    // 3. 项目经历改写
    var projText = '';
    state.projectExperiences.forEach(function(proj, i) {
      if (!proj || !proj.name) return;
      projText += '■ ' + proj.name + ' | ' + proj.role + '\n';
      if (proj.action) {
        projText += '  项目动作：\n';
        proj.action.split(/[\n\r]+/).forEach(function(line) {
          projText += '    • ' + line.replace(/^\d+[.、\)]\s*/, '') + '\n';
        });
      }
      if (proj.result) {
        projText += '  项目成果：\n';
        proj.result.split(/[\n\r]+/).forEach(function(line) {
          projText += '    ★ ' + line.replace(/^\d+[.、\)]\s*/, '') + '\n';
        });
      }
      projText += '\n';
    });
    if (!projText) projText = '【请在模块3中添加项目经历】';
    setOutput('output-project', projText.trim());

    // 4. 技能模块调整（优先岗位需要的）
    var skillsText = '';
    var hardSkills = val('analysis-hard-skills').split(/[\n,，、;；]+/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var resumeSkills = val('resume-skills').split(/[\n,，、;；]+/).map(function(s){return s.trim();}).filter(function(s){return s;});

    // 分类：岗位需要的（优先） + 其他
    var prioritized = [];
    var others = [];
    resumeSkills.forEach(function(skill) {
      var isPriority = false;
      hardSkills.forEach(function(hs) {
        if (skill.toLowerCase().indexOf(hs.toLowerCase()) !== -1 || hs.toLowerCase().indexOf(skill.toLowerCase()) !== -1) {
          isPriority = true;
        }
      });
      if (isPriority) prioritized.push(skill);
      else others.push(skill);
    });

    // 补充JD要求但简历中没有列出的技能
    var missingButRelevant = [];
    if (r) {
      r.hardMatched.forEach(function(s) {
        var alreadyListed = false;
        resumeSkills.forEach(function(rs) {
          if (rs.toLowerCase().indexOf(s.toLowerCase()) !== -1) alreadyListed = true;
        });
        if (!alreadyListed) missingButRelevant.push(s);
      });
    }

    if (prioritized.length > 0) {
      skillsText += '【核心技能】（岗位重点要求）\n';
      prioritized.forEach(function(s) { skillsText += '  • ' + s + '\n'; });
    }
    if (missingButRelevant.length > 0) {
      skillsText += '\n【建议补充】（简历已体现但未列出）\n';
      missingButRelevant.forEach(function(s) { skillsText += '  • ' + s + '\n'; });
    }
    if (others.length > 0) {
      skillsText += '\n【其他技能】\n';
      others.forEach(function(s) { skillsText += '  • ' + s + '\n'; });
    }
    if (!skillsText) skillsText = '【请在模块3中填写技能清单】';
    setOutput('output-skills', skillsText.trim());

    // 5. 最终简历版本
    var finalResume = '';
    finalResume += name + ' | ' + title + ' | ' + years + '经验\n';
    finalResume += '学历：' + education;
    if (val('resume-certificates')) finalResume += ' | 证书：' + val('resume-certificates');
    finalResume += '\n';
    finalResume += '求职意向：' + jobTitle;
    if (company) finalResume += ' @ ' + company;
    finalResume += '\n';
    finalResume += '\n━━━ 个人简介 ━━━\n' + intro + '\n';
    if (highlights) {
      finalResume += '\n━━━ 核心优势 ━━━\n';
      highlights.split(/[\n\r]+/).forEach(function(line) {
        finalResume += line.replace(/^\d+[.、\)]\s*/, '') + '\n';
      });
    }
    finalResume += '\n━━━ 工作经历 ━━━\n' + workText.trim() + '\n';
    if (projText && projText.indexOf('请在模块3') === -1) {
      finalResume += '\n━━━ 项目经历 ━━━\n' + projText.trim() + '\n';
    }
    finalResume += '\n━━━ 技能清单 ━━━\n' + skillsText.trim() + '\n';
    finalResume += '\n━━━ 教育背景 ━━━\n' + education + '\n';

    setOutput('output-final', finalResume.trim());

    showToast('优化简历已生成！');
  }

  function setOutput(id, content) {
    var el = $(id);
    el.textContent = content;
    el.classList.remove('empty');
  }

