  // ========== 数据持久化 ==========

  function saveToStorage() {
    try {
      var data = {
        keywords: state.keywords,
        workExperiences: state.workExperiences,
        projectExperiences: state.projectExperiences,
        fields: {
          'job-company': val('job-company'),
          'job-industry': val('job-industry'),
          'job-title': val('job-title'),
          'job-level': val('job-level'),
          'job-salary': val('job-salary'),
          'job-location': val('job-location'),
          'job-education': val('job-education'),
          'job-duties': val('job-duties'),
          'job-requirements': val('job-requirements'),
          'job-preferences': val('job-preferences'),
          'analysis-core': val('analysis-core'),
          'analysis-hard-skills': val('analysis-hard-skills'),
          'analysis-soft-skills': val('analysis-soft-skills'),
          'analysis-keywords': val('analysis-keywords'),
          'analysis-hidden': val('analysis-hidden'),
          'resume-name': val('resume-name'),
          'resume-current-title': val('resume-current-title'),
          'resume-years': val('resume-years'),
          'resume-education': val('resume-education'),
          'resume-certificates': val('resume-certificates'),
          'resume-skills': val('resume-skills'),
          'resume-highlights': val('resume-highlights')
        },
        matchResult: state.matchResult
      };
      localStorage.setItem('resume-workbench', JSON.stringify(data));
    } catch(e) {
      console.error('保存失败', e);
    }
  }

  function loadFromStorage() {
    try {
      var raw = localStorage.getItem('resume-workbench');
      if (!raw) return;
      var data = JSON.parse(raw);

      // 恢复表单字段
      if (data.fields) {
        Object.keys(data.fields).forEach(function(id) {
          setVal(id, data.fields[id]);
        });
      }

      // 恢复关键词
      if (data.keywords) {
        state.keywords = data.keywords;
        renderKeywordTags();
      }

      // 恢复工作经历
      if (data.workExperiences) {
        data.workExperiences.forEach(function(exp) {
          if (exp) addWorkExperience(exp);
        });
      }

      // 恢复项目经历
      if (data.projectExperiences) {
        data.projectExperiences.forEach(function(proj) {
          if (proj) addProjectExperience(proj);
        });
      }

      // 恢复匹配结果
      if (data.matchResult) {
        state.matchResult = data.matchResult;
        renderMatchResults();
      }
    } catch(e) {
      console.error('加载失败', e);
    }
  }

