  window.clearModule = function(n) {
    if (!confirm('确定清空模块' + n + '的所有内容吗？')) return;
    var fields = {
      1: ['job-company','job-industry','job-title','job-level','job-salary','job-location','job-education','job-duties','job-requirements','job-preferences'],
      2: ['analysis-core','analysis-hard-skills','analysis-soft-skills','analysis-keywords','analysis-hidden'],
      3: ['resume-name','resume-current-title','resume-years','resume-education','resume-certificates','resume-skills','resume-highlights']
    };
    if (fields[n]) {
      fields[n].forEach(function(id) { setVal(id, ''); });
    }
    if (n === 1) {
      state.keywords = [];
      renderKeywordTags();
    }
    if (n === 3) {
      state.workExperiences = [];
      state.projectExperiences = [];
      $('work-experience-list').innerHTML = '';
      $('project-experience-list').innerHTML = '';
    }
    saveToStorage();
    showToast('模块' + n + '已清空');
  };

